-- Cover any additional manually added catalog rows present when this migration runs.
UPDATE products
SET description_vi = 'Sản phẩm ' || TRIM(name_vi) ||
  CASE category
    WHEN 'Tops' THEN ' thuộc danh mục áo'
    WHEN 'Bottoms' THEN ' thuộc danh mục quần'
    WHEN 'Outerwear' THEN ' thuộc danh mục áo khoác'
    ELSE ''
  END ||
  CASE department
    WHEN 'Men' THEN ', dành cho nam'
    WHEN 'Women' THEN ', dành cho nữ'
    WHEN 'Kids' THEN ', dành cho trẻ em'
    ELSE ''
  END || '. Xem hình ảnh và thông tin sản phẩm để lựa chọn mẫu phù hợp.'
WHERE description_vi = '' AND TRIM(name_vi) <> '';
